var o=[{title:`Sinais a recolher`,text:`Compare as séries e as repetições que lhe foram dadas com o que concluiu. Veja a carga, o RPE da sessão, as dores musculares, as sessões em falta e quaisquer limitações novas, porque cada um mostra uma parte diferente do quadro. Um RPE alto ou um treino em falta não prova que o plano está errado para si.`},{title:`Quando as sessões parecem fáceis demais`,text:`Se continuar a atingir o objetivo com técnica estável e esforço baixo, pense em acrescentar algumas repetições, um pouco de carga ou um pouco mais de volume. Altere uma variável e veja como responde antes de acrescentar mais alguma coisa.`},{title:`Quando as sessões parecem difíceis demais`,text:`Falhar repetidamente os objetivos, uma técnica que se desfaz ou uma fadiga que não passa podem ser razões para reduzir a carga ou o volume, mudar para um exercício mais fácil ou fazer mais recuperação. Uma nova zona dolorosa exige que volte a olhar para as suas limitações e, possivelmente, que procure aconselhamento profissional. Não tente diagnosticá-la por si próprio.`},{title:`Exemplo`,text:`Faz agachamentos goblet 3 × 10 durante duas semanas com cerca de RPE 5 e bom controlo. Da próxima vez pode escolher um haltere ligeiramente mais pesado e voltar a oito repetições. Se o mesmo movimento continuar a doer, não se limite a torná-lo mais difícil.`},{title:`Usar o TrainUp`,text:`O seu plano só muda quando o gera de novo, e nunca com base em menos de 3 treinos. Qualquer dor recente significa que não há aumento. Se 2 dos seus últimos 3 treinos tiverem sido muito difíceis (RPE 9 ou mais) ou concluídos em menos de 60%, o plano seguinte é mais fácil. Se os seus últimos 4 tiverem sido fáceis (RPE 5 ou menos) e completos, fica um passo mais difícil, um passo de cada vez. As regras da dor vêm antes do desempenho, os treinos concluídos nunca são alterados e escolhe você a carga.`}];var s=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Orientações práticas do ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var i={sections:o,sources:s};export{i as default,o as sections,s as sources};